update public.content_variants set body = $json${"type":"case_study","answer":"This suggests a pyramid scheme because revenue depends on recruits, not product sales.","caseText":"Sari was invited to the skincare business. Entry package IDR 3,000,000. Big profits can be made if Sari recruits two friends, each of whom also has to buy a package of IDR 3,000,000. Sales of products to final consumers are hardly discussed.","followUp":{"answer":"Pyramid scheme","options":["Pyramid scheme","MLM is purely product based","Franchise franchise","Term savings"],"question":"What type of business is this?","explanation":"The main profits come from recruits and registration fees, not product sales."},"question":"Read the following cases and choose the best response.","difficulty":"beginner","explanation":"Pyramid schemes will collapse when there are no new members. Avoid businesses that emphasize recruiting rather than product sales."}$json$::jsonb where id = 'e7c4d48d-e538-4fba-823f-19d81735b4e3';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"Inflation means that the prices of goods and services increase generally over a certain period of time.","difficulty":"beginner","explanation":"Inflation is a continuous increase in general prices, not an increase in just one item."}$json$::jsonb where id = 'e912ae59-23ab-43db-a05a-fe1695f8dc59';
