update public.content_variants set body = $json${"type":"multiple_choice","answer":"Purchasing power is greater in Yogyakarta","options":["Purchasing power is greater in Yogyakarta","Purchasing power is greater in Jakarta","The purchasing power is the same because the nominal value is the same","IDR 50,000 can't buy chicken noodles in two cities"],"question":"Chicken noodles in Jakarta Rp. 18,000, in Yogyakarta Rp. 12,000. Which statement is correct regarding Rp. 50,000?","difficulty":"beginner","explanation":"With a cheaper price, the same money can buy more portions, meaning greater purchasing power."}$json$::jsonb where id = 'eadf4fdc-8b39-4e53-949c-c41995c3a90c';
