update public.content_variants set body = $json${"type":"multiple_choice","answer":"1.5 more novels in the online store","options":["1.5 more novels in the online store","No difference","Novels are cheaper in physical stores","Rp. 100,000 is not enough in two places"],"question":"Rina has IDR 100,000. The price of a used novel in online stores is IDR 25,000, in physical stores IDR 40,000. What is the difference in purchasing power in the number of novels?","difficulty":"beginner","explanation":"In the online shop IDR 100,000 can get 4 novels; in physical stores only 2.5 novels. The difference is 1.5 novels."}$json$::jsonb where id = 'f1fd8db9-568c-4812-bdac-29195e7496e5';

